/* Graph v9 preserves snapshot identity and installed empty lists; old graphs remain v8. */
#include "flashvm/execution.h"
#include "flashvm/standard.h"
#include "flashvm/serialization.h"
#include "flashvm/transfer.h"
#include "flashvm/gc.h"
#include "zlib.h"
#include "flashvm/capability.h"
#include "flashvm/extensions.h"
#include <stdio.h>
#include <assert.h>
static void obj(FVM_Value *v,FVM_Object *o){fvm_value_undefined(v);v->type=FVM_VALUE_OBJECT;v->object=o;}
static void put32(unsigned char *p,unsigned long v){p[0]=(unsigned char)(v>>24);p[1]=(unsigned char)(v>>16);p[2]=(unsigned char)(v>>8);p[3]=(unsigned char)v;}
static void repair(unsigned char *data,size_t size){put32(data+12,(unsigned long)crc32(0,data+16,(uInt)(size-16)));}
static void check(FVM_Context *c,const FVM_Value *root,unsigned empty){FVM_Value instance,alias,second,klass,out;assert(fvm_object_get(c,root->object,"instance",&instance)==FVM_OK && fvm_object_get(c,root->object,"alias",&alias)==FVM_OK && fvm_object_get(c,root->object,"second",&second)==FVM_OK && fvm_object_get(c,root->object,"class",&klass)==FVM_OK && fvm_exec_instance_of(c,&instance,&alias,&out)==FVM_OK && out.boolean==!empty);assert(fvm_exec_implements(c,&klass,1,&second)==FVM_OK && fvm_exec_instance_of(c,&instance,&second,&out)==FVM_OK && !out.boolean);}
int main(void){FVM_Config cfg;FVM_Runtime *rt;unsigned empty;assert(fvm_config_init(&cfg)==FVM_OK && fvm_runtime_create(&cfg,&rt)==FVM_OK);for(empty=0;empty<2;++empty){FVM_Context *c,*dst;FVM_Object *root,*klass,*target,*iface,*old,*fresh,*alias,*second,*second_proto,*instance;FVM_Value graph,type,arg,v,copy;unsigned char *data;size_t size;unsigned long before,after;FVM_Channel *channel;unsigned char swf[]={'F','W','S',8,16,0,0,0,8,0,0,12,1,0,0,0};assert(fvm_context_create(rt,&c)==FVM_OK && fvm_context_create(rt,&dst)==FVM_OK && fvm_load_memory(c,swf,sizeof(swf))==FVM_OK && fvm_load_memory(dst,swf,sizeof(swf))==FVM_OK && fvm_standard_install(c)==FVM_OK && fvm_standard_install(dst)==FVM_OK);assert(fvm_object_create(c,&root)==FVM_OK && fvm_gc_pin(c,root)==FVM_OK && fvm_object_create(c,&klass)==FVM_OK && fvm_object_create(c,&target)==FVM_OK && fvm_object_create(c,&iface)==FVM_OK && fvm_object_create(c,&old)==FVM_OK && fvm_object_create(c,&fresh)==FVM_OK && fvm_object_create(c,&alias)==FVM_OK && fvm_object_create(c,&second)==FVM_OK && fvm_object_create(c,&second_proto)==FVM_OK && fvm_object_create(c,&instance)==FVM_OK);obj(&graph,root);assert(fvm_value_serialize(c,&graph,&data,&size)==FVM_OK && data[7]==8);fvm_serialized_free(data);obj(&v,target);assert(fvm_object_set(c,klass,"prototype",&v)==FVM_OK && fvm_object_set_prototype(c,instance,target)==FVM_OK);obj(&v,old);assert(fvm_object_set(c,iface,"prototype",&v)==FVM_OK && fvm_object_set(c,alias,"prototype",&v)==FVM_OK);obj(&v,second_proto);assert(fvm_object_set(c,second,"prototype",&v)==FVM_OK);obj(&type,klass);obj(&arg,iface);if(empty)fvm_value_number(&arg,17);assert(fvm_exec_implements(c,&type,1,&arg)==FVM_OK);obj(&v,fresh);assert(fvm_object_set(c,iface,"prototype",&v)==FVM_OK);obj(&v,klass);assert(fvm_object_set(c,root,"class",&v)==FVM_OK);obj(&v,instance);assert(fvm_object_set(c,root,"instance",&v)==FVM_OK);obj(&v,alias);assert(fvm_object_set(c,root,"alias",&v)==FVM_OK);obj(&v,second);assert(fvm_object_set(c,root,"second",&v)==FVM_OK && fvm_gc_collect(c,0)==FVM_OK);check(c,&graph,empty);assert(fvm_value_serialize(c,&graph,&data,&size)==FVM_OK && data[7]==9 && fvm_gc_object_count(dst,&before)==FVM_OK);/* Plain root record starts at 29; its kind/state/prototype/meta occupy 17 bytes. */assert(data[46]==0);data[46]=2;repair(data,size);assert(fvm_value_deserialize(dst,data,size,&copy)==FVM_INVALID_ARGUMENT && fvm_gc_object_count(dst,&after)==FVM_OK && after==before);data[46]=0;repair(data,size);assert(fvm_value_deserialize(dst,data,size,&copy)==FVM_OK && fvm_gc_pin(dst,copy.object)==FVM_OK && fvm_gc_collect(dst,0)==FVM_OK);check(dst,&copy,empty);fvm_serialized_free(data);assert(fvm_channel_create(&channel)==FVM_OK && fvm_channel_send_value(c,channel,&graph,0)==FVM_OK && fvm_channel_receive_value(dst,channel,&copy,0)==FVM_OK && fvm_gc_pin(dst,copy.object)==FVM_OK && fvm_gc_collect(dst,0)==FVM_OK);check(dst,&copy,empty);fvm_channel_destroy(channel);assert(fvm_channel_open_file("interface-snapshot-test.bin","w",&channel)==FVM_OK && fvm_channel_send_value(c,channel,&graph,0)==FVM_OK);fvm_channel_destroy(channel);assert(fvm_channel_open_file("interface-snapshot-test.bin","r",&channel)==FVM_OK && fvm_channel_receive_value(dst,channel,&copy,0)==FVM_OK && fvm_gc_pin(dst,copy.object)==FVM_OK && fvm_gc_collect(dst,0)==FVM_OK);check(dst,&copy,empty);fvm_channel_destroy(channel);remove("interface-snapshot-test.bin");
#ifdef OS_PORTS
 {FVM_ResourceBroker *broker;FVM_Channel *queue,*network;FVM_Object *wrapper;char *uri;assert(fvm_broker_start("127.0.0.1","127.0.0.1",0,&broker)==FVM_OK && fvm_context_set_broker(c,broker)==FVM_OK && fvm_extensions_install(c)==FVM_OK && fvm_channel_create(&queue)==FVM_OK && fvm_extensions_wrap_channel(c,queue,&wrapper)==FVM_OK && fvm_broker_export(c,wrapper,&uri)==FVM_OK && fvm_channel_open_network(c,uri,&network)==FVM_OK);fvm_serialized_free(uri);assert(fvm_channel_send_value(c,network,&graph,0)==FVM_OK && fvm_channel_receive_value(dst,queue,&copy,0)==FVM_OK && fvm_gc_pin(dst,copy.object)==FVM_OK && fvm_gc_collect(dst,0)==FVM_OK);check(dst,&copy,empty);fvm_channel_release(network);fvm_channel_release(queue);fvm_broker_stop(broker);fvm_broker_release(broker);}
#endif
 fvm_context_destroy(dst);fvm_context_destroy(c);}fvm_runtime_destroy(rt);return 0;}
